sys_script_client.script:
function onLoad() {
    //As per MSSCUSTODY-3281, Make maker appropriate fields read only for checker on bulk form
    var taskType = g_scratchpad.blkTskRelated;
    if (taskType == 'Checker' || taskType == 'GHSS Handler') {
        g_form.setReadOnly('outcome', true);
        g_form.setReadOnly('reason_code', true);
        g_form.setReadOnly('reason_description', true);
        g_form.setReadOnly('advice', true);
        g_form.setReadOnly('suspend', true);
        g_form.setReadOnly('cancel_by', true);
        g_form.setVisible('current_maker_assignee', true);
    } else if (taskType == 'Maker')
        g_form.setVisible('current_maker_assignee', false);

}
